'use client';
import { useEffect, useId, useRef, useState, type CSSProperties, type KeyboardEvent } from 'react';
import { cx } from '../lib/cx';
import { useControllable, useIsoLayoutEffect } from '../lib/hooks';
import { Icon } from '../lib/icons';
import { useHoverGlide } from '../lib/glide';
import '../designme.css';
import './multi-select.css';

export interface MultiSelectOption {
  value: string;
  /** Defaults to the value */
  label?: string;
  /** Quiet text at the end of the row, like how many files carry the tag */
  meta?: string;
}

export interface MultiSelectProps {
  /** Like "Tags" */
  label: string;
  options: MultiSelectOption[];
  /** What's picked, in the order it was picked */
  value?: string[];
  defaultValue?: string[];
  onValueChange?: (value: string[]) => void;
  /** What's typed in the box. It filters the list */
  query?: string;
  defaultQuery?: string;
  onQueryChange?: (query: string) => void;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** Defaults to "Add a tag" */
  placeholder?: string;
  /** The quiet line under the box. Defaults to "Type to filter. Backspace removes the last tag." */
  hint?: string;
  /** Shown when nothing matches. Defaults to "No tags match" */
  empty?: string;
  /** The button beside the label that takes every pick off, shown while something is picked. Defaults to "Clear all" */
  clearLabel?: string;
  className?: string;
}

/** A combobox that keeps what you pick as chips. Typing filters the list, the arrow keys move through it, Enter picks
    or unpicks, Escape closes it, and Backspace in an empty box takes the last chip off. */
export function MultiSelect({ label, options, value, defaultValue = [], onValueChange, query, defaultQuery = '', onQueryChange, open, defaultOpen = false, onOpenChange,
  placeholder = 'Add a tag', hint = 'Type to filter. Backspace removes the last tag.', empty = 'No tags match', clearLabel = 'Clear all', className }: MultiSelectProps) {
  const id = 'dm-msc' + useId().replace(/:/g, '');
  const [picked, setPicked] = useControllable(value, defaultValue, onValueChange);
  const [q, setQ] = useControllable(query, defaultQuery, onQueryChange);
  const [isOpen, setOpen] = useControllable(open, defaultOpen, onOpenChange);
  const [hi, setHi] = useState(0);
  // typing (or a new query from outside) starts the highlight at the first match again
  const [seenQ, setSeenQ] = useState(q);
  if (seenQ !== q) { setSeenQ(q); if (q) setHi(0); }
  const field = useRef<HTMLDivElement>(null), input = useRef<HTMLInputElement>(null), list = useRef<HTMLDivElement>(null), root = useRef<HTMLDivElement>(null);
  useHoverGlide(list, '.dm-msc-o');
  const [place, setPlace] = useState<CSSProperties>({}), pop = useRef<HTMLDivElement>(null);
  const name = (v: string) => options.find(o => o.value === v)?.label ?? v;
  const shown = options.filter(o => !q.trim() || (o.label ?? o.value).toLowerCase().includes(q.trim().toLowerCase()));
  const at = Math.min(hi, Math.max(0, shown.length - 1));

  // the list hangs 6px under the box, which grows as the chips wrap, or stands 6px over it when the room under it in the window
  // is too short; its height at its tallest decides, so typing a filter never moves it to the other side
  const up = useRef(false), was = useRef(false);
  useIsoLayoutEffect(() => {
    const r = root.current, f = field.current, p = pop.current, l = list.current; if (!r || !f || !p || !l) return;
    if (isOpen && !was.current) {
      const b = f.getBoundingClientRect(), tall = p.offsetHeight - l.offsetHeight + (parseFloat(getComputedStyle(l).maxHeight) || l.offsetHeight);
      up.current = b.bottom + tall + 12 > innerHeight && b.top - tall - 12 > innerHeight - b.bottom;
    }
    was.current = isOpen;
    setPlace(up.current ? { top: 'auto', bottom: r.offsetHeight - f.offsetTop + 6, ['--dm-origin' as string]: 'bottom left' } : { top: f.offsetTop + f.offsetHeight + 6, bottom: 'auto', ['--dm-origin' as string]: 'top left' });
  }, [picked.length, isOpen]);
  // the highlighted row stays in view
  useEffect(() => { const o = list.current?.querySelector<HTMLElement>(`#${id}-o${at}`), l = list.current; if (!o || !l) return;
    if (o.offsetTop < l.scrollTop) l.scrollTop = o.offsetTop; else if (o.offsetTop + o.offsetHeight > l.scrollTop + l.clientHeight) l.scrollTop = o.offsetTop + o.offsetHeight - l.clientHeight; }, [at, id, isOpen]);
  // a click outside closes it
  useEffect(() => {
    if (!isOpen) return;
    const off = (e: PointerEvent) => { if (!root.current?.contains(e.target as Node)) setOpen(false); };
    document.addEventListener('pointerdown', off); return () => document.removeEventListener('pointerdown', off);
  }, [isOpen, setOpen]);

  const toggle = (v: string) => {
    setPicked(picked.includes(v) ? picked.filter(x => x !== v) : [...picked, v]);
    setQ(''); setHi(Math.max(0, options.findIndex(o => o.value === v)));
  };
  const onKey = (e: KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
      e.preventDefault();
      if (!isOpen) { setOpen(true); setHi(0); return; }
      if (shown.length) setHi((at + (e.key === 'ArrowDown' ? 1 : -1) + shown.length) % shown.length);
    }
    else if (e.key === 'Enter') { e.preventDefault(); if (isOpen && shown[at]) toggle(shown[at].value); else setOpen(true); }
    else if (e.key === 'Escape') { if (isOpen) { e.preventDefault(); setOpen(false); } }
    else if (e.key === 'Backspace' && !q && picked.length) setPicked(picked.slice(0, -1));
    else if (e.key === 'Tab') setOpen(false);
  };

  return (
    <div ref={root} data-dm="" className={cx('dm-msc', className)}>
      {/* Clear all takes every chip off at once; the cursor goes back to the box, so the next tag can be typed straight away */}
      <div className="dm-msc-top">
        <label className="dm-msc-l" htmlFor={`${id}-q`}>{label}</label>
        {picked.length > 0 && <button type="button" className="dm-msc-clr" onMouseDown={e => e.preventDefault()} onClick={() => { setPicked([]); input.current?.focus(); }}>{clearLabel}</button>}
      </div>
      <div ref={field} className="dm-msc-f" onClick={e => { if ((e.target as Element).closest('.dm-msc-c')) return; input.current?.focus(); setOpen(true); }}>
        {picked.map(v => (
          <span key={v} className="dm-msc-c">{name(v)}
            <button type="button" aria-label={`Remove ${name(v)}`} onClick={e => { e.stopPropagation(); setPicked(picked.filter(x => x !== v)); }}><Icon name="x" size="xs" /></button>
          </span>
        ))}
        <input ref={input} id={`${id}-q`} className="dm-msc-q" role="combobox" aria-expanded={isOpen} aria-controls={`${id}-l`} aria-autocomplete="list" aria-haspopup="listbox"
          aria-activedescendant={isOpen && shown.length ? `${id}-o${at}` : undefined} value={q} placeholder={placeholder} spellCheck={false} autoComplete="off"
          onChange={e => { setQ(e.target.value); setHi(0); setOpen(true); }} onKeyDown={onKey} />
      </div>
      <div ref={pop} className={cx('dm-pop dm-msc-pop', isOpen && 'dm-open')} inert={!isOpen} style={place}>
        <div ref={list} id={`${id}-l`} className="dm-msc-list" role="listbox" aria-multiselectable="true" aria-label={label}>
          {shown.length ? shown.map((o, i) => (
            <div key={o.value} id={`${id}-o${i}`} role="option" aria-selected={picked.includes(o.value)} className={cx('dm-msc-o', i === at && 'dm-hl')}
              onMouseMove={() => { if (i !== at) setHi(i); }} onMouseDown={e => e.preventDefault()} onClick={() => toggle(o.value)}>
              <span className="dm-bx"><Icon name="check" size="xs" /></span>{o.label ?? o.value}{o.meta && <span className="dm-n dm-num">{o.meta}</span>}
            </div>
          )) : <div className="dm-msc-none">{empty}</div>}
        </div>
      </div>
      {hint && <span className="dm-muted dm-msc-h">{hint}</span>}
    </div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Multi-select ---------- */
/* a combobox that keeps what you pick as chips: typing filters the list, the arrows move through it, Enter picks or
   unpicks, Escape closes it, and Backspace in an empty box takes the last chip off. As wide as the other single fields; the
   list opens from the box (placePop) and the box glides up with it, so the two sit centred together (centre()). The rows'
   checkboxes stand on the column the box's words start on, 12px in, and their counts end 12px in */
.dm-msc{position:relative;width:100%;max-width:var(--dm-field-w);margin:0 auto;display:flex;flex-direction:column;gap:6px}
.dm-msc-top{display:flex;align-items:center;justify-content:space-between;gap:var(--dm-s-2);min-height:22px}
.dm-msc-l{font-size:12.5px;font-weight:500}
.dm-msc-clr{height:22px;padding:0 6px;margin-right:-6px;border-radius:calc(6px * var(--dm-rk-s,var(--dm-rk)));font-size:12px;color:var(--dm-muted);transition:color .2s,background .2s}
@media (hover:hover) and (pointer:fine){.dm-msc-clr:hover{color:var(--dm-fg);background:var(--dm-row)}}
/* (its chips and its text box are all 26px tall: the lines they wrap onto are centred in the box) */
.dm-msc-f{position:relative;display:flex;flex-wrap:wrap;align-items:flex-start;align-content:center;gap:6px;min-height:var(--dm-field-h);padding:6px;border-radius:var(--dm-r-field);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent);cursor:text;transition:box-shadow var(--dm-t-fast)}
@supports (corner-shape:squircle){.dm-msc-f{corner-shape:squircle;border-radius:var(--dm-r-field-sq)}}
/* the edge steps up while its search box has the focus or its list is open; a tag's remove button rings on its own, never
   inside the field */
.dm-msc-f:has(.dm-msc-q:focus),.dm-msc:has(.dm-msc-pop.dm-open) .dm-msc-f{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
.dm-msc-q{flex:1;min-width:80px;height:26px;border:0;outline:0;background:transparent;padding:0 6px;font:inherit;font-size:13.5px;color:var(--dm-fg)}
.dm-msc-q::placeholder{color:var(--dm-muted)}
.dm-msc-c{display:inline-flex;align-items:center;gap:2px;height:26px;padding:0 3px 0 var(--dm-s-2);border-radius:var(--dm-r-tag);background:var(--dm-chip);font-size:12.5px;white-space:nowrap}
@supports (corner-shape:squircle){.dm-msc-c{corner-shape:squircle;border-radius:var(--dm-r-tag-sq)}}
.dm-msc-c button{width:20px;height:20px;border-radius:50%;display:grid;place-items:center;color:var(--dm-muted);transition:background .2s,color .2s}
@media (hover:hover) and (pointer:fine){.dm-msc-c button:hover{background:color-mix(in srgb,currentColor 12%,transparent);color:var(--dm-fg)}}
.dm-msc-c.dm-go{animation:dm-mscout .22s var(--dm-ease) forwards}
@keyframes dm-mscout{to{opacity:0;transform:scale(.85)}}
/* the key just pressed, while the preview plays, at the end of the line the cursor is on */
.dm-msc-key{position:absolute;right:8px;bottom:10px;opacity:0;transition:opacity .2s}
.dm-msc-key.dm-on{opacity:1}
.dm-msc-pop{left:0;right:0;min-width:0}
/* (the rows are placed against the list itself, so keeping the highlighted one in view scrolls by the list's own measure) */
.dm-msc-list{position:relative;max-height:210px;overflow-y:auto;display:flex;flex-direction:column;gap:2px}
.dm-msc-o{display:flex;align-items:center;gap:10px;min-height:34px;padding:6px;border-radius:calc(9px * var(--dm-rk-m,var(--dm-rk)));font-size:13px;cursor:pointer;flex:none;transition:background var(--dm-t-fast)}
.dm-msc-o.dm-hl{background:var(--dm-row)}
.dm-msc-o .dm-bx{width:16px;height:16px;border-radius:var(--dm-r-tiny,5px);box-shadow:inset 0 0 0 1.5px var(--dm-fg2);display:grid;place-items:center;color:transparent;flex:none;transition:background .2s,box-shadow .2s,color .2s}
.dm-msc-o[aria-selected="true"] .dm-bx{background:var(--dm-accent);box-shadow:inset 0 0 0 1px var(--dm-accent-mark,var(--dm-accent));color:var(--dm-on-accent)}
.dm-msc-o .dm-n{margin-left:auto;font-size:12px;color:var(--dm-muted);transition:color var(--dm-t-fast)}
/* on a highlighted row's grey the count steps up, so it keeps 4.5:1 and APCA Lc 60 in dark mode */
.dm-msc-o.dm-hl .dm-n{color:var(--dm-fg2)}
.dm-msc-none{padding:var(--dm-s-2) 6px;font-size:12.5px;color:var(--dm-muted)}
.dm-msc-h{font-size:12px;transition:opacity var(--dm-t-fast) var(--dm-ease)}
/* the open list covers the hint under the box, so the hint steps aside instead of peeking out above the list */
.dm-msc:has(.dm-msc-pop.dm-open) .dm-msc-h{opacity:0}
/* Clean: the chips are tags with rounded corners, not pills; the list has the menus' 22px corners and its rows follow them;
   a checkbox is a rounded square with an inner shadow, ink once ticked (as Permission gate's) */
:root[data-style="clean"] .dm-msc-c,:root [data-style="clean"] .dm-msc-c,:root [data-style="clean"].dm-msc-c{border-radius:var(--dm-r-sm)}
:root[data-style="clean"] .dm-msc-pop,:root [data-style="clean"] .dm-msc-pop,:root [data-style="clean"].dm-msc-pop{border-radius:var(--dm-r-card)}
:root[data-style="clean"] .dm-msc-o,:root [data-style="clean"] .dm-msc-o,:root [data-style="clean"].dm-msc-o{border-radius:calc(var(--dm-r-card) - 6px)}
:root[data-style="clean"] .dm-msc-clr,:root [data-style="clean"] .dm-msc-clr,:root [data-style="clean"].dm-msc-clr{border-radius:var(--dm-r-pill)}
:root[data-style="clean"] .dm-msc-c button,:root [data-style="clean"] .dm-msc-c button,:root [data-style="clean"].dm-msc-c button{transition:background-color var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease)}
:root[data-style="clean"] .dm-msc-o .dm-bx,:root [data-style="clean"] .dm-msc-o .dm-bx,:root [data-style="clean"].dm-msc-o .dm-bx{border-radius:calc(3px * var(--dm-rk-s,var(--dm-rk)));background:var(--dm-surface);box-shadow:inset 0 0 0 1.5px var(--dm-fg2),var(--dm-track-ring)}
:root[data-style="clean"] .dm-msc-o[aria-selected="true"] .dm-bx,:root [data-style="clean"] .dm-msc-o[aria-selected="true"] .dm-bx,:root [data-style="clean"].dm-msc-o[aria-selected="true"] .dm-bx{background:linear-gradient(180deg,var(--dm-btn-1),var(--dm-btn-2));box-shadow:inset 0 0 0 1px var(--dm-btn-2),inset 0 2px 3px -1px rgba(255,255,255,.28);color:var(--dm-on-btn)}
